try:
    target = __loader__
except BaseException as error:
    actual = [(name, 'target-unavailable', type(error).__name__, str(error), error.args) for name in names]
else:
    actual = []
    for name in names:
        try:
            found = False
            for base in target.__mro__:
                if name in base.__dict__:
                    member = base.__dict__[name]
                    actual.append((name, base.__module__ + '.' + base.__name__, type(member).__name__, base is target))
                    found = True
                    break
            if not found:
                actual.append((name, 'missing'))
        except BaseException as error:
            actual.append((name, type(error).__name__, str(error), error.args))
print(repr(actual))

